const data = $input.first().json;

if (!data.valid) {
  return [];
}

const {
  toolCallId,
  functionName,
  date,
  timePreference,
  timezone,
  meetingDurationMinutes,
} = data;

// Horario comercial de NovaWeb Studio
const availabilityWindows = {
  morning: [
    {
      start: "10:00",
      end: "14:00",
    },
  ],
  afternoon: [
    {
      start: "16:00",
      end: "18:00",
    },
  ],
  any: [
    {
      start: "10:00",
      end: "14:00",
    },
    {
      start: "16:00",
      end: "18:00",
    },
  ],
};

const selectedWindows =
  availabilityWindows[timePreference] ??
  availabilityWindows.any;

const timeToMinutes = (time) => {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
};

const minutesToTime = (totalMinutes) => {
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  return `${String(hours).padStart(2, "0")}:${String(
    minutes
  ).padStart(2, "0")}`;
};

// Convierte una fecha y hora de Europe/Madrid a UTC.
// De esta manera también se respetan los cambios de horario de verano.
const localDateTimeToUtc = (
  dateString,
  totalMinutes,
  timeZone
) => {
  const [year, month, day] = dateString
    .split("-")
    .map(Number);

  const hour = Math.floor(totalMinutes / 60);
  const minute = totalMinutes % 60;

  const desiredUtcValue = Date.UTC(
    year,
    month - 1,
    day,
    hour,
    minute,
    0
  );

  let utcGuess = desiredUtcValue;

  const formatter = new Intl.DateTimeFormat("en-GB", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  });

  // Ajustamos iterativamente la diferencia entre UTC y Europe/Madrid.
  for (let attempt = 0; attempt < 3; attempt++) {
    const parts = formatter.formatToParts(
      new Date(utcGuess)
    );

    const values = {};

    for (const part of parts) {
      if (part.type !== "literal") {
        values[part.type] = Number(part.value);
      }
    }

    const formattedUtcValue = Date.UTC(
      values.year,
      values.month - 1,
      values.day,
      values.hour,
      values.minute,
      values.second
    );

    const difference =
      desiredUtcValue - formattedUtcValue;

    utcGuess += difference;

    if (difference === 0) {
      break;
    }
  }

  return new Date(utcGuess);
};

const minimumNoticeMilliseconds =
  2 * 60 * 60 * 1000;

const earliestAllowedTime =
  Date.now() + minimumNoticeMilliseconds;

const candidates = [];

let slotIndex = 0;

for (const window of selectedWindows) {
  const windowStart = timeToMinutes(window.start);
  const windowEnd = timeToMinutes(window.end);

  for (
    let startMinutes = windowStart;
    startMinutes + meetingDurationMinutes <= windowEnd;
    startMinutes += meetingDurationMinutes
  ) {
    const endMinutes =
      startMinutes + meetingDurationMinutes;

    const startUtc = localDateTimeToUtc(
      date,
      startMinutes,
      timezone
    );

    const endUtc = localDateTimeToUtc(
      date,
      endMinutes,
      timezone
    );

    // Evita ofrecer citas con menos de dos horas de antelación.
    if (startUtc.getTime() < earliestAllowedTime) {
      continue;
    }

    candidates.push({
      json: {
        toolCallId,
        functionName,
        date,
        timePreference,
        timezone,
        meetingDurationMinutes,

        slotIndex,
        localStartTime: minutesToTime(startMinutes),
        localEndTime: minutesToTime(endMinutes),

        startTime: startUtc.toISOString(),
        endTime: endUtc.toISOString(),

        noCandidates: false,
      },
      pairedItem: {
        item: 0,
      },
    });

    slotIndex++;
  }
}

if (candidates.length === 0) {
  return [
    {
      json: {
        ...data,
        noCandidates: true,
        reason:
          "No quedan horarios candidatos que cumplan el tiempo mínimo de antelación",
      },
    },
  ];
}

return candidates;

const input = $input.first().json;
const payload = input.body ?? input;
const message = payload.message ?? {};

const EXPECTED_FUNCTION_NAME = "consultar_disponibilidad";
const TIMEZONE = "Europe/Madrid";
const MEETING_DURATION_MINUTES = 30;
const MAX_ADVANCE_DAYS = 30;

// --------------------------------------------------
// 1. Localizar las llamadas de herramienta
// --------------------------------------------------

let toolCalls = [];

if (Array.isArray(message.toolCallList)) {
  toolCalls = message.toolCallList;
} else if (Array.isArray(message.toolCalls)) {
  toolCalls = message.toolCalls;
} else if (Array.isArray(message.toolWithToolCallList)) {
  toolCalls = message.toolWithToolCallList.map(
    (entry) => entry.toolCall ?? entry
  );
}

const toolCall = toolCalls[0] ?? null;

// --------------------------------------------------
// 2. Extraer argumentos
// --------------------------------------------------

let args =
  toolCall?.arguments ??
  toolCall?.parameters ??
  toolCall?.function?.arguments ??
  {};

if (typeof args === "string") {
  try {
    args = JSON.parse(args);
  } catch {
    args = {};
  }
}

if (!args || typeof args !== "object" || Array.isArray(args)) {
  args = {};
}

// --------------------------------------------------
// 3. Normalizar los datos
// --------------------------------------------------

const toolCallId = String(toolCall?.id ?? "").trim();

const functionName = String(
  toolCall?.name ??
  toolCall?.function?.name ??
  ""
).trim();

const date = String(
  args.date ??
  args.fecha ??
  ""
).trim();

const rawTimePreference = String(
  args.timePreference ??
  args.time_preference ??
  args.franja ??
  ""
)
  .trim()
  .toLowerCase();

const allowedPreferences = [
  "morning",
  "afternoon",
  "any",
];

const timePreference = allowedPreferences.includes(rawTimePreference)
  ? rawTimePreference
  : rawTimePreference;

// --------------------------------------------------
// 4. Funciones para validar fechas
// --------------------------------------------------

const parseCalendarDate = (value) => {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);

  if (!match) {
    return null;
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  const parsedDate = new Date(
    Date.UTC(year, month - 1, day)
  );

  const isRealDate =
    parsedDate.getUTCFullYear() === year &&
    parsedDate.getUTCMonth() === month - 1 &&
    parsedDate.getUTCDate() === day;

  return isRealDate ? parsedDate : null;
};

const getCurrentDateInTimezone = (timezone) => {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date());

  const values = {};

  for (const part of parts) {
    if (part.type !== "literal") {
      values[part.type] = part.value;
    }
  }

  return `${values.year}-${values.month}-${values.day}`;
};

// --------------------------------------------------
// 5. Validación
// --------------------------------------------------

const errors = [];

if (!toolCall) {
  errors.push(
    "No se ha encontrado ninguna llamada de herramienta"
  );
}

if (!toolCallId) {
  errors.push(
    "Falta el identificador de la llamada de herramienta"
  );
}

if (!functionName) {
  errors.push(
    "Falta el nombre de la función"
  );
} else if (functionName !== EXPECTED_FUNCTION_NAME) {
  errors.push(
    `La función recibida es "${functionName}", pero se esperaba "${EXPECTED_FUNCTION_NAME}"`
  );
}

const requestedDate = parseCalendarDate(date);

if (!date) {
  errors.push(
    "Falta la fecha solicitada"
  );
} else if (!requestedDate) {
  errors.push(
    "La fecha debe ser una fecha real con formato YYYY-MM-DD"
  );
}

if (!rawTimePreference) {
  errors.push(
    "Falta la preferencia horaria"
  );
} else if (!allowedPreferences.includes(rawTimePreference)) {
  errors.push(
    'La preferencia horaria debe ser "morning", "afternoon" o "any"'
  );
}

// --------------------------------------------------
// 6. Reglas de negocio de la fecha
// --------------------------------------------------

const todayString = getCurrentDateInTimezone(TIMEZONE);
const todayDate = parseCalendarDate(todayString);

let daysInAdvance = null;
let isWeekend = false;

if (requestedDate && todayDate) {
  daysInAdvance = Math.round(
    (requestedDate.getTime() - todayDate.getTime()) /
      (24 * 60 * 60 * 1000)
  );

  const dayOfWeek = requestedDate.getUTCDay();
  isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

  if (daysInAdvance < 0) {
    errors.push(
      "No se puede consultar disponibilidad para una fecha pasada"
    );
  }

  if (daysInAdvance > MAX_ADVANCE_DAYS) {
    errors.push(
      `Solo se puede consultar disponibilidad con un máximo de ${MAX_ADVANCE_DAYS} días de antelación`
    );
  }

  if (isWeekend) {
    errors.push(
      "NovaWeb Studio no ofrece reuniones los sábados ni los domingos"
    );
  }
}

// --------------------------------------------------
// 7. Resultado normalizado
// --------------------------------------------------

return [
  {
    json: {
      toolCallId,
      functionName,
      date,
      timePreference,

      timezone: TIMEZONE,
      meetingDurationMinutes: MEETING_DURATION_MINUTES,

      currentDate: todayString,
      daysInAdvance,
      isWeekend,

      valid: errors.length === 0,
      errors,
    },
  },
];

const data = $input.first().json;

const toolCallId = String(
  data.toolCallId ?? ""
).trim();

const errors = Array.isArray(data.errors)
  ? data.errors.filter(Boolean)
  : [];

const toolResult = {
  status: "invalid_request",
  date: data.date || null,
  timezone: data.timezone || "Europe/Madrid",
  reasons:
    errors.length > 0
      ? errors
      : ["No se puede consultar la fecha solicitada"],
  instruction:
    "Explica brevemente el motivo al usuario y solicita otra fecha válida. No digas que se ha producido un error técnico.",
};

return [
  {
    json: {
      results: [
        {
          toolCallId,
          result: JSON.stringify(toolResult),
        },
      ],
    },
  },
];

const data = $input.first().json;

const toolCallId = String(
  data.toolCallId ?? ""
).trim();

const toolResult = {
  status: "no_availability",
  date: data.date || null,
  timezone: data.timezone || "Europe/Madrid",
  reason:
    data.reason ||
    "No quedan horarios disponibles que cumplan el tiempo mínimo de antelación",
  instruction:
    "Indica que ya no quedan horarios válidos para esa fecha y pide al usuario otra fecha o franja. No lo presentes como un error técnico.",
};

return [
  {
    json: {
      results: [
        {
          toolCallId,
          result: JSON.stringify(toolResult),
        },
      ],
    },
  },
];

const calendarResults = $input.all();

const candidateSlots = $(
  "Generar horarios candidatos"
).all();

if (calendarResults.length !== candidateSlots.length) {
  throw new Error(
    `El número de resultados de Calendar (${calendarResults.length}) no coincide con el número de horarios candidatos (${candidateSlots.length})`
  );
}

// Relacionar cada resultado de Calendar con su horario original.
const checkedSlots = calendarResults.map(
  (calendarItem, index) => {
    const candidate = candidateSlots[index].json;

    const available =
      calendarItem.json.available === true ||
      calendarItem.json.available === "true";

    return {
      ...candidate,
      available,
    };
  }
);

const firstSlot = checkedSlots[0];

if (!firstSlot) {
  throw new Error(
    "No se han recibido horarios para comprobar"
  );
}

const {
  toolCallId,
  date,
  timezone,
  meetingDurationMinutes,
} = firstSlot;

const availableSlots = checkedSlots.filter(
  (slot) => slot.available
);

// Seleccionar un máximo de tres horarios distribuidos.
const selectDistributedSlots = (
  slots,
  maximum = 3
) => {
  if (slots.length <= maximum) {
    return slots;
  }

  if (maximum === 1) {
    return [slots[0]];
  }

  const selectedIndexes = new Set();

  for (let index = 0; index < maximum; index++) {
    const position = Math.round(
      (index * (slots.length - 1)) /
        (maximum - 1)
    );

    selectedIndexes.add(position);
  }

  return [...selectedIndexes].map(
    (position) => slots[position]
  );
};

const selectedSlots = selectDistributedSlots(
  availableSlots,
  3
);

// Etiqueta pensada únicamente para la conversación.
const dateForFormatting = new Date(
  `${date}T12:00:00.000Z`
);

const dateLabel = new Intl.DateTimeFormat(
  "es-ES",
  {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }
).format(dateForFormatting);

// Caso sin disponibilidad.
if (selectedSlots.length === 0) {
  const toolResult = {
    status: "no_availability",

    // Fecha para uso técnico.
    date,

    // Fecha para que Lucía la pronuncie.
    dateLabel,

    timezone,
    availableSlots: [],
    message:
      "No hay horarios disponibles para la fecha solicitada. Pide al usuario otra fecha o franja horaria.",
  };

  return [
    {
      json: {
        results: [
          {
            toolCallId,
            result: JSON.stringify(toolResult),
          },
        ],
      },
    },
  ];
}

// Caso con disponibilidad.
const slotsForVapi = selectedSlots.map(
  (slot) => ({
    start: slot.localStartTime,
    end: slot.localEndTime,
    startUtc: slot.startTime,
    endUtc: slot.endTime,
  })
);

const toolResult = {
  status: "available",

  // Siempre mantiene YYYY-MM-DD.
  date,

  // Solo se utiliza para hablar con el usuario.
  dateLabel,

  timezone,
  durationMinutes: meetingDurationMinutes,
  availableSlots: slotsForVapi,
  instruction:
    "Ofrece estos horarios al usuario y espera a que elija uno. No reserves todavía.",
};

return [
  {
    json: {
      results: [
        {
          toolCallId,
          result: JSON.stringify(toolResult),
        },
      ],
    },
  },
];
